<script setup lang="ts">
import { onMounted, ref, computed } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import * as api from '@/api/lab'; import type { Lab } from '@/types/lab'
const rows=ref<Lab[]>([]),q=ref(''),loading=ref(false),dialog=ref(false),editing=ref(false),form=ref<Lab>({labId:0,labName:'',labLocation:'',labRemark:''});const filtered=computed(()=>rows.value.filter(x=>x.labName.includes(q.value)|| (x.labLocation||'').includes(q.value)));async function load(){loading.value=true;try{rows.value=await api.getLabs()}finally{loading.value=false}}function open(row?:Lab){editing.value=!!row;form.value=row?{...row}:{labId:0,labName:'',labLocation:'',labRemark:''};dialog.value=true}async function save(){if(!form.value.labName||!form.value.labLocation)return ElMessage.warning('实验室名称和位置必填');const ok=editing.value?await api.updateLab(form.value.labId,form.value):await api.createLab(form.value);if(ok!==false){ElMessage.success('保存成功');dialog.value=false;load()}}async function remove(row:Lab){await ElMessageBox.confirm(`确定删除“${row.labName}”吗？`,'提示',{type:'warning'});if(await api.deleteLab(row.labId)){ElMessage.success('删除成功');load()}}onMounted(load)
</script>
<template><div class="page"><div class="page-header"><h2>实验室管理</h2><el-button type="primary" @click="open()">新增实验室</el-button></div><div class="card"><div class="filters"><el-input v-model="q" clearable placeholder="搜索名称或位置" style="max-width:280px"/></div><el-table :data="filtered" v-loading="loading" empty-text="暂无数据"><el-table-column prop="labName" label="实验室名称"/><el-table-column prop="labLocation" label="位置"/><el-table-column prop="labRemark" label="备注"/><el-table-column label="操作" width="180"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" :title="editing?'编辑实验室':'新增实验室'" width="480px"><el-form label-width="90px"><el-form-item label="名称"><el-input v-model="form.labName"/></el-form-item><el-form-item label="位置"><el-input v-model="form.labLocation"/></el-form-item><el-form-item label="备注"><el-input v-model="form.labRemark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
